def main():
    dest=O/'authored-narratives-v2'
    if dest.exists():raise FileExistsError('Preserve authored draft')
    tok=BPE.load(O.parent/'tokenizer-8192');dest.mkdir();files={};stats={}
    for split,names in [('development',['Mara','Nolan','Tessa','Felix','Dora']),('final',['Iona','Rufus','Petra','Silas','Willa'])]:
        rows=[]
        assert len(FRAMES[split])==20
        for frame,(template,facts) in enumerate(FRAMES[split]):
            for name in names:
                prefix=template.format(name=name);ident=f'{split}:authored-narrative:{len(rows):03d}'
                assert 30<=len(prefix.split())<=60
                ids=tok.encode(prefix);assert tok.decode(ids)==prefix
                rows.append(dict(id=ident,prefix=prefix,prefix_token_ids=ids,entity=name,template_family=f'{split}:narrative-frame:{frame:02d}',
                    premise_facts=facts,origin='assistant_authored_evaluation_only',generation_seed=int.from_bytes(hashlib.sha256(ident.encode()).digest()[:4],'big'),
                    temperature=.7,top_p=.9,minimum_words=80,maximum_words=120,early_eos_failure_below_words=40))
        p=dest/(split+'-narrative.jsonl');p.write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rows));files[p.name]=hashlib.sha256(p.read_bytes()).hexdigest()
        stats[split]={'items':len(rows),'template_families':20,'minimum_prefix_tokens':min(len(r['prefix_token_ids']) for r in rows),'maximum_prefix_tokens':max(len(r['prefix_token_ids']) for r in rows)}
    result=dict(status='DRAFT_NOT_FROZEN',files_sha256=files,statistics=stats,tokenizer_manifest_sha256=hashlib.sha256((O.parent/'tokenizer-8192/manifest.json').read_bytes()).hexdigest(),
        authoring_review='All 40 frames and explicit facts reviewed by the authoring assistant for coherent unresolved situations; name substitutions are mechanical. No independent human review or model scoring.',
        interpretation='100 instances but only 20 scenario families per split. Endings need not follow a predetermined solution. Premise facts are grading aids, not required repetitions in generated text.',
        limitations=['Research evaluation only; not broad conversation or tool capability certification.','New lexical and combined ancestry checks still required.','Same assistant authored and reviewed; do not claim independent semantic certification.'])
    (dest/'receipt.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
if __name__=='__main__':main()
